type Cache={data:any;at:number;pending?:Promise<any>;albums:Record<string,any>;artists:Record<string,any>;issues?:any;ui?:any}
const caches=new Map<string,Cache>()
window.addEventListener('saved-data-changed',()=>{for(const c of caches.values()){c.data=null;c.at=0;c.albums={};c.artists={};c.issues=undefined;c.pending=undefined}})
function cacheFor(){const key=JSON.stringify([getAccount()?.id||'server',getAccount()?.admin,getAccount()?.can_library_issues,getAccount()?.lidarr_enabled]);if(!caches.has(key))caches.set(key,{data:null,at:0,albums:{},artists:{}});return caches.get(key)!}
function fetchLibrary(c:Cache,force=false){if(!c.pending){const pending=request<any>('/api/library?view=directory&limit=2000'+(force?'&refresh=true':'')).then(d=>{c.data=d;c.at=Date.now();return d}).finally(()=>{if(c.pending===pending)c.pending=undefined});c.pending=pending}return c.pending}
function PathLink({value}:{value:string}){const [open,setOpen]=useState(false);return value?<><button className="path-link" onClick={()=>setOpen(!open)} title={value}>{value}</button>{open&&<input readOnly value={value} aria-label="Select file path" onFocus={e=>e.target.select()}/>}</>:<span className="muted">Not mapped</span>}
function Artwork({src,label,className='' }:{src?:string;label:string;className?:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);return src&&!failed?<img className={className} src={src} alt="" loading="lazy" referrerPolicy="no-referrer" onError={()=>setFailed(true)}/>:<div className={`library-art-placeholder ${className}`} aria-label={`No artwork for ${label}`}>{label.trim().slice(0,1).toUpperCase()||'♫'}</div>}
function ServiceMark({provider}:{provider:'lidarr'|'plex'|'musicbrainz'|'apple'|'spotify'}){
 if(provider==='lidarr')return <img src="/lidarr-logo.png" alt=""/>
 if(provider==='apple')return <img src="/apple-music-logo.svg" alt=""/>
 if(provider==='plex')return <svg viewBox="0 0 32 32" role="img"><path d="M8 4h7l9 12-9 12H8l9-12z"/></svg>
 if(provider==='spotify')return <svg viewBox="0 0 32 32" role="img"><circle cx="16" cy="16" r="13"/><path className="logo-cut" d="M8.5 11.7c5.8-1.7 12.4-1 16.7 1.5M9.7 16.2c4.8-1.3 10.4-.7 14 1.3M10.8 20.3c3.9-1 8.2-.5 11.2 1.2"/></svg>
 if(provider==='musicbrainz')return <svg viewBox="0 0 32 32" role="img"><path d="M16 2 29 9.5v13L16 30 3 22.5v-13z"/><path className="logo-cut filled" d="M8 20h2V12H8zm3.5 4h2V8h-2zm3.5-2h2V10h-2zm3.5 3h2V7h-2zm3.5-5h2v-8h-2z"/></svg>
 return <svg viewBox="0 0 32 32" role="img"><path d="M16 3a13 13 0 1 0 13 13A13 13 0 0 0 16 3m0 4a9 9 0 0 1 8.5 6H20a5 5 0 0 0-8 0H7.5A9 9 0 0 1 16 7m0 18a9 9 0 0 1-8.5-6H12a5 5 0 0 0 8 0h4.5a9 9 0 0 1-8.5 6"/><circle cx="16" cy="16" r="3"/></svg>
}
function ServiceLink({name,provider,url,onClick}:{name:string;provider:'lidarr'|'plex'|'musicbrainz'|'apple'|'spotify';url?:string;onClick?:()=>void}){const label=url?`Open in ${name}`:`Link or find on ${name}`,content=<><span className={`service-mark ${provider}`} aria-hidden="true"><ServiceMark provider={provider}/></span><span className="sr-only">{label}</span></>;if(!url&&!onClick)return null;return url?<a className="service-icon linked" href={url} target="_blank" rel="noreferrer" title={label} aria-label={label} data-label={name}>{content}</a>:<button className="service-icon unlinked" onClick={onClick} title={label} aria-label={label} data-label={name}>{content}</button>}
function AttentionPanel({title,issues,close,openAlbum}:{title:string;issues:any[];close:()=>void;openAlbum?:(id:string)=>void}){return <section className="panel library-attention-panel"><div className="panel-head"><div><h2>{title}</h2><p>{issues.length?`${issues.length} finding${issues.length===1?'':'s'} from the latest inventory and file audit.`:'No detailed findings are currently available. Refresh the relevant inventories.'}</p></div><button onClick={close}>Close</button></div>{issues.map((issue:any)=><article key={issue.issue_id||`${issue.issue}-${issue.id||issue.plex_id||issue.title}`}><div><strong>{issue.issue||'Needs attention'}</strong><p>{[issue.album,issue.title].filter(Boolean).join(' · ')}</p><small>{issue.reason||'Review the current Lidarr, Plex, and file associations.'}</small></div><div className="actions">{openAlbum&&issue.album_id&&<button onClick={()=>openAlbum(String(issue.album_id))}>Review Album</button>}{issue.plex_url&&<a href={issue.plex_url} target="_blank" rel="noreferrer">Open Plex ↗</a>}</div></article>)}</section>}
function releaseType(row:any){return ['Album','EP','Single'].includes(row.type)?row.type:'Other'}
function isLive(row:any){return (row.secondary_types||[]).some((value:string)=>value.toLowerCase()==='live')}
function releaseStatus(row:any){
 if(row.library_state==='In Library')return {tone:'available',icon:'✓',text:row.status||'In Library'}
 if(row.library_state==='Wanted')return {tone:'downloading',icon:'↓',text:row.status||'Wanted'}
 return {tone:'missing',icon:'−',text:row.status||'Missing'}
}
function savedDirectoryView(){try{return localStorage.getItem('playlist-bridge-library-view')==='table'?'table':'cards'}catch{return 'cards'}}

